// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface VerbalOrderIn {
  patient_id?: number | null;
  ticket_id?: number | null;
  admission_id?: number | null;
  encounter_id?: number | null;
  /** Derived from ticket/admission if omitted */
  source?: "OPD" | "IPD" | "CodeRed" | "ER" | null;
  /** The doctor's toggle: Hospital Pharmacy vs External/Local Market; only ExternalMarket while the dispensing service is not Active (CAPABILITY_INACTIVE) */
  destination?: "HospitalPharmacy" | "ExternalMarket";
  notes?: string | null;
  items: RxItemIn[];
  /** The doctor who gave the order (employee id) (GET /staff/lookup) */
  prescriber_id: number;
  order_mode: "Verbal" | "Telephone";
  /** The order was read back to the prescriber, who confirmed it */
  read_back: true;
}

export interface RxItemIn {
  /** A drug of the hospital's list: required for the hospital pharmacy; on an outside slip (ExternalMarket) its high-alert and look-alike checks then follow it on the ward */
  drug_id?: number | null;
  /** Outside slip only: the typed name of a medicine that is not on the hospital's list (it carries no high-alert flag) */
  external_drug_name?: string | null;
  external_strength?: string | null;
  external_form?: string | null;
  /** In lowest units (e.g. 15 tablets) */
  qty_prescribed: number | string;
  dose_text?: string | null;
  route?: "Oral" | "IV" | "IM" | "SC" | "Topical" | "Inhaled" | "PR" | "SL" | "Ophthalmic" | "Otic" | "Nasal" | "Other" | null;
  frequency_code?: "OD" | "BD" | "TDS" | "QID" | "Q4H" | "Q6H" | "Q8H" | "Q12H" | "HS" | "STAT" | "PRN" | "Other" | null;
  interval_hours?: number | null;
  duration_days?: number | null;
  instructions?: string | null;
  /** Required for inpatient orders (MAR) */
  start_at?: string | null;
  end_at?: string | null;
  is_prn?: boolean;
  is_stat?: boolean;
  /** Inpatients: the patient may take it themselves (MSDS 70): an oral, inhaled or topical medicine that is not high-alert, from the hospital pharmacy or bought outside (an outside line with a drug_id of the hospital's list, never a typed name; decisions 59) */
  self_administration?: boolean;
}

