/** Write down a verbal or telephone order — POST /api/v1/prescriptions/verbal (who may call: holders of prescription.verbal.record). */
export function recordVerbal(body: VerbalOrderIn): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("POST", `/prescriptions/verbal`, body, { idempotent: true });
}

/** Verbal orders and their countersignatures — GET /api/v1/verbal-orders (who may call: holders of prescription.view or prescription.verbal.record). */
export function listVerbalOrders(query?: { mine?: boolean; pending?: boolean; admission_id?: number | null; limit?: number }): Promise<VerbalOrderOut[]> {
  return api<VerbalOrderOut[]>("GET", withQuery(`/verbal-orders`, query), undefined);
}

/** Formulary search with live stock colour — GET /api/v1/drugs/search (who may call: holders of pharmacy.formulary.view). */
export function searchDrugs(query?: { q?: string; limit?: number }): Promise<DrugStockOut[]> {
  return api<DrugStockOut[]>("GET", withQuery(`/drugs/search`, query), undefined);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}
